const item = $input.first().json;

const fileName = (
  item["File Name"] || item.file_name || ''
).trim().toLowerCase();

const submitter = (
  item["Submitted By"] || item.submitted_by || ''
).trim().toLowerCase();

const org = (
  item["Organization"] || item.organization || ''
).trim().toLowerCase();

const fingerprint = fileName || org || submitter || '';

return [{ json: {
  ...item,
  quick_tax_id:       '',
  duplicate_check_id: fingerprint,
  fingerprint:        fingerprint,
  fingerprint_type:   fileName ? 'filename'
                    : org      ? 'organization'
                    : 'submitter'
}}];

const incoming  = $('Filename Duplicate Check').first().json;
const rows      = $input.all();
const fp        = (incoming.fingerprint || '').toLowerCase();

const existingRows = rows.filter(r => {
  const f = (
    r.json['File Name'] || r.json['file_name'] || ''
  ).trim().toLowerCase();
  return f.length > 0 && f === fp;
});

const isDuplicate    = existingRows.length > 0;
const existingRecord = isDuplicate
  ? existingRows[existingRows.length - 1].json
  : null;

// ── Calculate cache freshness ──
let cacheHit   = false;
let hoursSince = 999;

if (existingRecord) {
  const completedRaw = 
    existingRecord['Completed At'] ||
    existingRecord['completed_at'] || '';

  if (completedRaw) {
    const completedAt = new Date(completedRaw);
    // Check it parsed correctly
    if (!isNaN(completedAt.getTime())) {
      hoursSince = (Date.now() - completedAt.getTime()) / 3600000;
      cacheHit   = hoursSince < 24;
    }
  }
}

// ── IMPORTANT: do NOT spread ...incoming ──
// Build output fresh so no stale cache_hit leaks through
return [{ json: {
  // Carry forward only what we need
  "Request ID":      incoming["Request ID"]    || incoming.request_id,
  "Received At":     incoming["Received At"]   || incoming.received_at,
  "Completed At":    incoming["Completed At"]  || incoming.received_at,
  "Submitted By":    incoming["Submitted By"]  || incoming.submitted_by,
  "Email":           incoming["Email"]         || incoming.submission_email,
  "Organization":    incoming["Organization"]  || incoming.organization,
  "File Name":       incoming["File Name"]     || incoming.file_name,
  pdf_base64:        incoming.pdf_base64,
  request_id:        incoming["Request ID"]    || incoming.request_id,
  submitted_by:      incoming["Submitted By"]  || incoming.submitted_by,
  submission_email:  incoming["Email"]         || incoming.submission_email,
  organization:      incoming["Organization"]  || incoming.organization,
  file_name:         incoming["File Name"]     || incoming.file_name,
  received_at:       incoming["Received At"]   || incoming.received_at,
  fingerprint:       incoming.fingerprint,
  fingerprint_type:  incoming.fingerprint_type,

  // ── Duplicate result — set explicitly, never from spread ──
  is_duplicate:          isDuplicate,
  cache_hit:             cacheHit,           // ← explicitly calculated
  hours_since_last_run:  parseFloat(hoursSince.toFixed(1)),
  existing_final_status: existingRecord ? (existingRecord['Final Status']      || '') : '',
  existing_risk_score:   existingRecord ? (existingRecord['Risk Score']         || 0)  : 0,
  existing_risk_level:   existingRecord ? (existingRecord['Risk Level']         || '') : '',
  existing_ai_summary:   existingRecord ? (existingRecord['AI Summary']         || '') : '',
  existing_completed_at: existingRecord ? (existingRecord['Completed At']       || '') : '',
  existing_request_id:   existingRecord ? (existingRecord['Request ID']         || '') : '',
  existing_entity_name:  existingRecord ? (existingRecord['Entity Name (Doc)']  || '') : '',
  existing_tax_id:       existingRecord ? (existingRecord['Tax ID Normalized']  || '') : '',

  // ── Debug (remove after confirmed) ──
  _debug_fp:             fp,
  _debug_rows_found:     existingRows.length,
  _debug_completed_raw:  existingRecord ? (existingRecord['Completed At'] || 'EMPTY') : 'NO_RECORD',
  _debug_hours:          parseFloat(hoursSince.toFixed(1)),
  _debug_cache_hit:      cacheHit
}}];

// ── INTAKE: normalize Lovable form payload ─────────────────────────────────
const body = $input.first().json.body || $input.first().json;

const requestId = 'TXID-'
  + new Date().toISOString().slice(0,10).replace(/-/g,'')
  + '-'
  + Math.random().toString(36).substring(2,8).toUpperCase();

const pdfBase64 = (body.pdf_base64 || '').replace(/^data:application\/pdf;base64,/, '');
const fileName  = body.file_name   || body.fileName || 'tax_document.pdf';
const submitter = body.submitted_by || body.name    || 'Unknown';
const email     = body.email        || '';
const org       = body.organization || '';

if (!pdfBase64) {
  throw new Error('NO_PDF: pdf_base64 field is empty or missing');
}

const now = new Date().toISOString();

return [{ json: {
  // ── Matches sheet Row 3 headers EXACTLY (capitals + spaces) ──
  "Request ID":           requestId,
  "Received At":          now,
  "Completed At":         now,
  "Submitted By":         submitter,
  "Email":                email,
  "Organization":         org,
  "File Name":            fileName,
  "Entity Name (Doc)":    '',
  "Tax ID Raw":           '',
  "Tax ID Normalized":    '',
  "Tax ID Type":          '',
  "Doc Type":             '',
  "Tax Year":             '',
  "Signature":            false,
  "Format Valid":         false,
  "Format Error":         '',
  "DB Match Score":       0,
  "DB Entity Name":       '',
  "DB Status":            '',
  "Name Mismatch":        false,
  "Final Status":         'PROCESSING',
  "Risk Level":           '',
  "Risk Score":           0,
  "AI Confidence":        0,
  "Compliance Flags":     '',
  "AI Summary":           '',
  "Recommended Action":   '',
  "Parse Confidence":     0,

  // ── Internal fields (not written to sheet, used by pipeline nodes) ──
  pdf_base64:             pdfBase64,
  request_id:             requestId,
  submitted_by:           submitter,
  submission_email:       email,
  organization:           org,
  file_name:              fileName,
  received_at:            now,
  status:                 'PROCESSING'
}}];

const item = $input.first().json;
const b64  = item.pdf_base64 || '';

let extractedText = '';

try {
  const buf = Buffer.from(b64, 'base64');
  const raw = buf.toString('binary');

  const found = [];

  // ── Pull all literal strings from PDF parenthesis notation (Tj / TJ ops) ──
  const parenStrings = raw.match(/\(([^\)\\]{1,200})\)/g) || [];
  for (const s of parenStrings) {
    const inner = s.slice(1, -1).trim();
    // Keep only strings with real alphanumeric content
    if (/[a-zA-Z0-9@\.\-]/.test(inner) && inner.length >= 2) {
      found.push(inner);
    }
  }

  // ── Directly scan for EIN / SSN / 9-digit patterns ──
  const eins = raw.match(/\b\d{2}[-\s]?\d{7}\b/g) || [];
  const ssns = raw.match(/\b\d{3}[-\s]?\d{2}[-\s]?\d{4}\b/g) || [];
  const nine = raw.match(/\b\d{9}\b/g) || [];

  // ── Also try UTF-8 decode for modern PDFs ──
  let utf8text = '';
  try {
    utf8text = Buffer.from(b64, 'base64').toString('utf8');
    // pull any lines that look like real text
    const lines = utf8text.split(/[\r\n]+/);
    for (const line of lines) {
      const clean = line.replace(/[^\x20-\x7E]/g, ' ').trim();
      if (clean.length > 4 && /[a-zA-Z]{2,}/.test(clean)) {
        found.push(clean);
      }
    }
  } catch(e) {}

  // ── Combine everything ──
  const allText = [
    ...found,
    ...eins,
    ...ssns,
    ...nine
  ].join(' ').replace(/\s+/g, ' ').trim();

  // ── Remove pure PDF operator noise ──
  extractedText = allText
    .replace(/\b(obj|endobj|stream|endstream|xref|trailer|startxref|BT|ET)\b/g, ' ')
    .replace(/\/(BaseFont|Subtype|Encoding|Type|FontDescriptor|WinAnsiEncoding|Name)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .substring(0, 5000)
    .trim();

} catch(e) {
  extractedText = '[extraction error: ' + e.message + ']';
}

return [{
  json: {
    ...item,
    pdf_text:     extractedText || '[no readable text found]',
    pdf_text_len: extractedText.length
  }
}];

