const item = $input.first().json;
const prev = $('Normalize Lovable Payload1').first().json;

let raw = '';
try {
  raw = item.choices[0].message.content;
} catch(e) {
  raw = '';
}

raw = raw.replace(/\\n/g, ' ').replace(/\n/g, ' ').trim();

let parsed = {};
try {
  parsed = JSON.parse(raw);
} catch(e) {
  const match = raw.match(/\{[\s\S]+\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch(e2) {
      parsed = {
        tax_id: '', tax_id_raw: '', tax_id_type: 'UNKNOWN',
        entity_name: '', doc_type: 'UNKNOWN',
        tax_year: null, signature_present: false,
        parse_confidence: 0,
        parse_notes: 'Parse failed: ' + e.message
      };
    }
  }
}

return [{
  json: {
    // ── Sheet headers (capitals + spaces) ──
    "Request ID":        prev["Request ID"]    || prev.request_id,
    "Received At":       prev["Received At"]   || prev.received_at,
    "Completed At":      prev["Completed At"]  || prev.received_at,
