    "Tax ID Raw":        parsed.tax_id_raw     || parsed.tax_id || '',
    "Tax ID Normalized": parsed.tax_id         || '',
    "Tax ID Type":       parsed.tax_id_type    || 'UNKNOWN',
    "Doc Type":          parsed.doc_type       || 'UNKNOWN',
    "Tax Year":          parsed.tax_year       || '',
