const item = $input.first().json;
const rawId  = item["Tax ID Normalized"] || item.tax_id_normalized ||
               item["Tax ID Raw"]        || item.tax_id_raw        ||
               item.tax_id              || '';
const taxType = item["Tax ID Type"] || item.tax_id_type || 'UNKNOWN';

let ok = false, normalized = rawId.replace(/-/g,''), err = null;
const raw = normalized;

if (taxType === 'EIN' && /^\d{9}$/.test(raw)) {
  const prefix = parseInt(raw.substring(0,2));
  const bad    = [0,7,8,9,17,18,19,28,29,49,69,70,78,79,89,96,97];
  normalized   = raw.substring(0,2) + '-' + raw.substring(2);
  ok           = !bad.includes(prefix);
  if (!ok) err = 'EIN prefix ' + prefix + ' is not a valid IRS-assigned prefix';

} else if (taxType === 'SSN' && /^\d{9}$/.test(raw)) {
  normalized = raw.substring(0,3)+'-'+raw.substring(3,5)+'-'+raw.substring(5);
  if (raw==='+1234567890'||raw.substring(0,3)==='000'||raw.substring(3,5)==='00'||raw.substring(5)==='0000') {
    err = 'SSN contains all-zero segment'; ok = false;
  } else if (raw.substring(0,3)==='666'||parseInt(raw.substring(0,3))>=900) {
    err = 'SSN area 666 or 900-999 is invalid'; ok = false;
  } else { ok = true; }

} else if (taxType === 'ITIN' && /^\d{9}$/.test(raw)) {
  normalized = raw.substring(0,3)+'-'+raw.substring(3,5)+'-'+raw.substring(5);
  ok = raw[0]==='9' && ['70','71','72','73','74','75','76','77','78','79',
       '80','81','82','83','84','85','86','87','88'].includes(raw.substring(3,5));
  if (!ok) err = 'ITIN must start with 9 and have specific 4th-5th digit values';

} else if (taxType === 'VAT' && raw.length >= 5) {
  normalized = raw.toUpperCase(); ok = true;

} else if (raw.length >= 5) {
  ok = true;
  err = 'Tax ID type unrecognized — proceeding with caution';

} else {
  err = 'Tax ID too short or unrecognized for type ' + taxType;
}

if (ok && /^(.)\1+$/.test(raw)) {
  ok = false; err = 'Tax ID is all repeating digits — invalid';
}

return [{ json: {
  ...item,
  // ── Sheet-header keys ──
  "Tax ID Normalized": normalized,
  "Format Valid":      ok,
  "Format Error":      err || '',
  // ── Internal keys ──
  normalized_tax_id:   normalized,
  format_valid:        ok,
  format_error:        err || ''
}}];

const incoming = $('Format Validation1').first().json;

// ── THIS is the only line that was wrong — reads BOTH formats ──
const submittedRaw =
  incoming["Tax ID Normalized"] ||
  incoming["Tax ID Raw"]        ||
  incoming.normalized_tax_id    ||
  incoming.tax_id_raw           ||
  incoming.tax_id               || '';

const submitted = submittedRaw.replace(/-/g, '').toUpperCase();

const dbRows = $input.all();
let matchedRow = null, matchScore = 0;

for (const row of dbRows) {
  const d     = row.json;
  const rawId = d['Tax ID'] || d['tax_id'] || d['TAX ID'] || '';
  const dbId  = rawId.replace(/[^0-9A-Za-z]/g, '').toUpperCase();
  if (!dbId) continue;
  if (dbId === submitted) { matchedRow = d; matchScore = 100; break; }
  if (dbId.substring(0,6) === submitted.substring(0,6) && submitted.length >= 6) {
    matchedRow = d; matchScore = 60;
  }
}

const exact   = matchScore === 100;
const partial = matchScore === 60;

const dbName  = matchedRow ? (matchedRow['Entity Name']              || matchedRow['entity_name']              || '') : '';
const dbStat  = matchedRow ? (matchedRow['Status']                   || matchedRow['status']                   || 'NOT_FOUND') : 'NOT_FOUND';
const dbActive= matchedRow ? (matchedRow['Active Since']             || matchedRow['active_since']             || '') : '';
const dbType  = matchedRow ? (matchedRow['Tax ID Type']              || matchedRow['tax_id_type']              || '') : '';
const dbState = matchedRow ? (matchedRow['Registered State']         || matchedRow['registered_state']         || '') : '';
const dbSource= matchedRow ? (matchedRow['Source']                   || matchedRow['source']                   || '') : '';
const dbLastV = matchedRow ? (matchedRow['Last Verified']            || matchedRow['last_verified']            || '') : '';
const dbLastR = matchedRow ? (matchedRow['Last Verification Result'] || matchedRow['last_verification_result'] || '') : '';
const dbRisk  = matchedRow ? (matchedRow['Last Risk Score']          || matchedRow['last_risk_score']          || '') : '';
const dbNotes = matchedRow ? (matchedRow['Notes']                    || matchedRow['notes']                    || '') : '';

const entityFromDoc = incoming["Entity Name (Doc)"] || incoming.entity_name || '';
const formatValid   = incoming["Format Valid"] ?? incoming.format_valid ?? false;

let nameMismatch = false;
if (exact && dbName && entityFromDoc) {
  const clean   = s => s.toLowerCase().replace(/[^a-z0-9 ]/g,'').split(' ').filter(w => w.length > 2);
  const overlap = clean(dbName).filter(w => clean(entityFromDoc).includes(w)).length;
  nameMismatch  = overlap === 0;
}

let vr = 'UNVERIFIED';
if (!formatValid)                                          vr = 'FORMAT_INVALID';
else if (!exact && !partial)                               vr = 'NOT_IN_DATABASE';
else if (exact && dbStat.toUpperCase().includes('REVOK'))  vr = 'REVOKED';
else if (exact && dbStat.toUpperCase().includes('SUSPEND'))vr = 'SUSPENDED';
else if (exact && nameMismatch)                            vr = 'ID_NAME_MISMATCH';
else if (partial && !exact)                                vr = 'POSSIBLE_MATCH_REVIEW';
else if (exact)                                            vr = 'VERIFIED';

return [{ json: {
  ...incoming,
  // ── Sheet-header keys ──
  "DB Match Score":  matchScore,
  "DB Entity Name":  dbName,
  "DB Status":       dbStat,
  "Name Mismatch":   nameMismatch,
  "Final Status":    vr,
  // ── Internal keys ──
  db_match_score:      matchScore,
  db_exact_match:      exact,
  db_partial_match:    partial,
  db_entity_name:      dbName,
  db_status:           dbStat,
  db_active:           dbActive,
  db_type:             dbType,
  db_state:            dbState,
  db_source:           dbSource,
  db_last_verified:    dbLastV,
  db_last_result:      dbLastR,
  db_risk_score:       dbRisk,
  db_notes:            dbNotes,
  db_row:              matchedRow,
  name_mismatch:       nameMismatch,
  verification_result: vr,
  is_verified:         vr === 'VERIFIED',
  format_valid:        formatValid,
  looked_up_at:        new Date().toISOString(),
  // ── Debug (remove after confirmed working) ──
  _debug_submitted:    submitted,
  _debug_raw_field:    submittedRaw,
  _debug_rows:         dbRows.length
}}];

// ── Groq raw response comes via $input ──
const inputJson = $input.first().json;

// ── DB + document fields come from the named upstream node ──
const incoming = $('Database Lookup + Match Logic1').first().json;

// ── Parse Groq verdict from choices[0].message.content ──
let groqVerdict = {};
try {
  const raw =
    inputJson?.choices?.[0]?.message?.content ||
    inputJson?.content ||
    inputJson?.message?.content ||
    '{}';
  const cleaned = raw.replace(/```json|```/gi, '').trim();
  groqVerdict = JSON.parse(cleaned);
} catch (e) {
  groqVerdict = {};
}

const aiSummary         = groqVerdict.summary            || groqVerdict.ai_summary          || '';
const riskLevel         = groqVerdict.risk_level         || '';
const riskScore         = groqVerdict.risk_score         ?? 0;
const aiConfidence      = groqVerdict.confidence         ?? groqVerdict.ai_confidence       ?? 0;
const complianceFlags   = groqVerdict.flags              || groqVerdict.compliance_flags    || [];
const recommendedAction = groqVerdict.recommended_action || '';
const parseConfidence   = groqVerdict.parse_confidence   ?? groqVerdict.confidence          ?? 0;

// ── Read Tax ID ──
const submittedRaw =
  incoming["Tax ID Normalized"] ||
  incoming.tax_id_normalized    ||
  incoming["Tax ID Raw"]        ||
  incoming.tax_id_raw           ||
  incoming.tax_id               || '';
const submitted = submittedRaw.replace(/-/g, '').toUpperCase();

// ── Read DB match results (already computed upstream) ──
const matchScore = incoming["DB Match Score"] ?? incoming.db_match_score ?? 0;
const exact      = matchScore === 100;
const partial    = matchScore === 60;

const dbName   = incoming["DB Entity Name"]           || incoming.db_entity_name   || '';
const dbStat   = incoming["DB Status"]                || incoming.db_status        || 'NOT_FOUND';
const dbActive = incoming["Active Since"]             || incoming.db_active        || '';
const dbType   = incoming["Tax ID Type"]              || incoming.db_type          || '';
const dbState  = incoming["Registered State"]         || incoming.db_state         || '';
const dbSource = incoming["Source"]                   || incoming.db_source        || '';
const dbLastV  = incoming["Last Verified"]            || incoming.db_last_verified || '';
const dbLastR  = incoming["Last Verification Result"] || incoming.db_last_result   || '';
const dbRisk   = incoming["Last Risk Score"]          || incoming.db_risk_score    || '';
const dbNotes  = incoming["Notes"]                    || incoming.db_notes         || '';
const dbRow    = incoming.db_row                      || null;

// ── Name similarity check ──
let nameMismatch = false;
const entityFromDoc = incoming["Entity Name (Doc)"] || incoming.entity_name || '';
if (exact && dbName && entityFromDoc) {
  const clean   = s => s.toLowerCase().replace(/[^a-z0-9 ]/g, '').split(' ').filter(w => w.length > 2);
  const overlap = clean(dbName).filter(w => clean(entityFromDoc).includes(w)).length;
  nameMismatch  = overlap === 0;
}

// ── Verification result ──
const formatValid = incoming["Format Valid"] ?? incoming.format_valid ?? false;
let vr = 'UNVERIFIED';
if (!formatValid)                                           vr = 'FORMAT_INVALID';
else if (!exact && !partial)                                vr = 'NOT_IN_DATABASE';
else if (exact && dbStat.toUpperCase().includes('REVOK'))   vr = 'REVOKED';
else if (exact && dbStat.toUpperCase().includes('SUSPEND')) vr = 'SUSPENDED';
else if (exact && nameMismatch)                             vr = 'ID_NAME_MISMATCH';
else if (partial && !exact)                                 vr = 'POSSIBLE_MATCH_REVIEW';
else if (exact)                                             vr = 'VERIFIED';

return [{ json: {
  // ── Document fields ──
  "Request ID":          incoming["Request ID"]    || incoming.request_id    || '',
  "Submitted By":        incoming["Submitted By"]  || incoming.submitted_by  || '',
  "Email":               incoming["Email"]         || incoming.email         || '',
  "Organization":        incoming["DB Entity Name"]  || incoming.organization  || '',
  "File Name":           incoming["File Name"]     || incoming.file_name     || '',
  "Entity Name (Doc)":   entityFromDoc,
  "Tax ID Raw":          incoming["Tax ID Raw"]    || incoming.tax_id_raw    || '',
  "Tax ID Normalized":   submittedRaw,
  "Tax ID Type":         dbType || incoming["Tax ID Type"] || '',
  "Format Valid":        formatValid,
  "Format Error":        incoming["Format Error"]  || incoming.format_error  || '',
  "Signature":           incoming["Signature"]     ?? incoming.signature     ?? false,

  // ── DB match results ──
  "DB Match Score":      matchScore,
  "DB Entity Name":      dbName,
  "DB Status":           dbStat,
  "DB Active Since":     dbActive,
  "DB Tax ID Type":      dbType,
  "DB State":            dbState,
  "DB Source":           dbSource,
  "DB Last Verified":    dbLastV,
  "DB Last Result":      dbLastR,
  "DB Risk Score":       dbRisk,
  "DB Notes":            dbNotes,
  "Name Mismatch":       nameMismatch,

  // ── Verdict ──
  "Final Status":        vr,

  // ── AI / Groq fields ──
  "Risk Level":          riskLevel,
  "Risk Score":          riskScore,
  "AI Confidence":       aiConfidence,
  "Compliance Flags":    Array.isArray(complianceFlags) ? complianceFlags.join(', ') : complianceFlags,
  "AI Summary":          aiSummary,
  "Recommended Action":  recommendedAction,
  "Parse Confidence":    parseConfidence,

  // ── Internal pipeline keys ──
